# Read the latest part of the conversation log and look for demo-like patterns
# Demos are input-output pairs, which would include two grids each

with open('/home/ubuntu/runs/paper/qwen-h0-u4-own/play/users/u001/system/state/sessions/01a19153-2323-715d-af92-ac8189281dc6.jsonl', 'r') as f:
    content = f.read()

# Extract all message content
import json
messages = []
for line in content.split('\n'):
    if line.strip():
        msg = json.loads(line)
        if msg.get('type') == 'message':
            messages.append(msg)

print(f"Found {len(messages)} messages")
print("\nMost recent messages:")
for msg in messages[-8:]:
    role = msg.get('message', {}).get('role', 'unknown')
    print(f"Role: {role}")
    content = msg.get('message', {}).get('content', '')
    if isinstance(content, list):
        for item in content:
            if item.get('type') == 'text':
                text = item.get('text', '')
                if len(text) > 200:
                    text = text[:200] + '...'
                print(text[:500])

